def check(x, n, m, k):
    """
    检查给编号 k 的储物格分配 x 个物资是否可行
    n: 储物格总数, m: 物资总量, k: 目标储物格编号
    """
    if x == 0:
        return True

    needed = x  # 编号 k 自身需要的物资

    # 左侧最少物资计算
    left_kids = k - 1
    if left_kids > 0:
        l = min(left_kids, x - 1)
        needed += l * x - l * (l + 1) // 2
        if left_kids > l:
            needed += (left_kids - l)

    # 右侧最少物资计算
    right_kids = n - k
    if right_kids > 0:
        r = min(right_kids, x - 1)
        needed += r * x - r * (r + 1) // 2
        if right_kids > r:
            needed += (right_kids - r)

    return needed <= m


def solve():
    n, m, k = map(int, input().split())
    low, high = 1, m
    ans = 0

    while low <= high:
        mid = low + (high - low) // 2
        if check(mid, n, m, k):
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    print(ans)


if __name__ == "__main__":
    solve()
